 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The output is a 3x2 tiling of the input, each tile rotated 180 degrees
    # around the central symmetry of the full mosaic.
    out = []
    for tr in range(3):
        for r in range(h):
            rr = h - 1 - r if tr % 2 == 0 else r
            row = []
            for tc in range(2):
                for c in range(w):
                    cc = w - 1 - c if tc == 0 else c
                    row.append(grid[rr][cc])
            out.append(row)
    return out
